package main
import("context";"fmt";"log";"net/http";"os";"os/signal";"syscall";"time";"github.com/ABHILASH9519/lunarreg-workbench/backend/go/internal/httpapi";"github.com/ABHILASH9519/lunarreg-workbench/backend/go/internal/jobs")
func main(){addr:=env("HTTP_ADDR",":8080");store,e:=jobs.Open(context.Background(),os.Getenv("DATABASE_URL"));if e!=nil{log.Fatalf("open job store: %v",e)};defer store.Close();api:=httpapi.New(store,env("CV_WORKER_URL","http://cv-worker:8000"),env("UPLOAD_DIR","./data/uploads"),int64Env("MAX_UPLOAD_BYTES",100*1024*1024));srv:=&http.Server{Addr:addr,Handler:api.Handler(),ReadHeaderTimeout:5*time.Second,ReadTimeout:2*time.Minute,WriteTimeout:2*time.Minute,IdleTimeout:60*time.Second};go func(){log.Printf("LunarReg Go API listening on %s",addr);if e:=srv.ListenAndServe();e!=nil&&e!=http.ErrServerClosed{log.Fatalf("HTTP server: %v",e)}}();stop:=make(chan os.Signal,1);signal.Notify(stop,syscall.SIGINT,syscall.SIGTERM);<-stop;ctx,cancel:=context.WithTimeout(context.Background(),15*time.Second);defer cancel();if e:=srv.Shutdown(ctx);e!=nil{log.Printf("shutdown: %v",e)}}
func env(k,d string)string{if v:=os.Getenv(k);v!=""{return v};return d}
func int64Env(k string,d int64)int64{if v:=os.Getenv(k);v!=""{var n int64;if _,e:=fmt.Sscan(v,&n);e==nil&&n>0{return n}};return d}
